5 //This class describes the whole chain of racks to which one sequencer is connected
6 class CDeviceRack : public CDevice
7 {
8 public:
9     uint16_t LastValue;
10     //uint8_t MyRackAddress;
11 public:
12     CDeviceRack(
13         CDeviceSequencer* _MySequencer//,
14         //unsigned int _MyRackAddress = 0xFE
15     );
16     virtual ~CDeviceRack() = default;
17     //virtual bool SetValue(unsigned int SubAddress, uint8_t* Data, unsigned long DataLength);
18     //virtual bool GetValue(unsigned int SubAddress, uint8_t* Data, unsigned long DataLength);
19     //virtual bool Configure();
20 
21     virtual bool SetValue(const unsigned int& SubAddress, const uint8_t* Data, const unsigned long& DataLength_in_bit, const uint8_t& StartBit);
22     //virtual bool SetValue(unsigned int SubAddress, uint8_t* Data, unsigned long DataLength);
23     //virtual bool GetValue(unsigned int SubAddress, uint8_t* Data, unsigned long DataLength);
24     //virtual bool Configure();
25 
26     virtual bool SelectRackSlot(const uint8_t& RackNr, const uint8_t& SlotNr) {
27         //This conversion will need to be adjusted to each type of backplane or if we enable slot selection in enchained racks
28         uint8_t SlotAddr = (SlotNr <= 3) ? (SlotNr + 12) : (SlotNr - 4);
29         
30         uint8_t Data = (SlotAddr & 0x0F) | ((RackNr & 0x07) << 4);
31         return SetValue(0, &Data, 7, 0);
32     }
33 
34     virtual bool ResetI2CMultiplexer() {
35         //Here we assume that the bus uses a slow speed, so that the first-break-then-make logic of the arbiter has time to work.
36         //We need to test how fast one can go like this. As the delay between break and set of new demux input is 20ns, and the remaining delay is monoflop controlled, it should be fine up to 50MHz.
37         uint8_t Data = 1;
38         bool success = SetValue(0, &Data, 1, 7);
39         MySequencer->Wait_ms(0.01);
40         Data = 0;
41         success = success && SetValue(0, &Data, 1, 7);
42         MySequencer->Wait_ms(0.01);
43         return success;
44     }
45 };
